import{_ as t,c as s,o as n,j as e,a as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"易图通变卷四","description":"易图通变 - 易图通变卷四","frontmatter":{"title":"易图通变卷四","description":"易图通变 - 易图通变卷四"},"headers":[],"relativePath":"zh/classics/yitu-tongbian/005.md","filePath":"zh/classics/yitu-tongbian/005.md"}'),r={name:"zh/classics/yitu-tongbian/005.md"};function o(l,a,c,d,p,u){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"易图通变卷四",tabindex:"-1"},[i("易图通变卷四 "),e("a",{class:"header-anchor",href:"#易图通变卷四","aria-label":"Permalink to “易图通变卷四”"},"​")],-1),e("p",null,"钦定四库全书",-1),e("p",null,"宋雷思齐撰",-1),e("p",null,"河之有图，虙牺则之以画八卦，文王因之以系卦辞。历代宝而传之，自见于书之顾命、陈之东序者，而今乃谓其无，谁敢哉？然自记以思，古则云其「出语之伤」，今则云其「不出顾已」，皆意之而非其真见矣。秦火之后，独见于书传孔安国之云而已。汉志杂以图书，而徒谓其与书经纬表里，易纬则徒又枝辞蔓引，愈违本旨，以至茫乎莫之究其有无形似之真为何如者，讫于唐、五季也。及宋之初，陈抟图南始创古，推明象数，闵其贱用于阴阳家之起例，而芜没于乾凿度，太一取其数以行九宫之法，起而著为龙图，以行于世。愚幸及其全书，观其离合出入，具于制数之说，若刳心而有以求羲、文之心者也。然实有不得于羲、文之心者，于本图之外，就以五十有五之数别出一图，自标之以为形洛书者，已是其初之失也。虽其纵横错综、分合体用之意皆在本图，而五十有五之数既离而别出，世遂舍本逐末，因疑图、书并出，虽是若非，无以究其诣极，而徒长纷纷之论。至其传及刘牧长民，因之泛出五十五图，名以「钩隐」，则又以增异。而时则李觏泰伯即駮其非是，然又自谓存其及见此三图，则其首即所传今谓河图者，其二即所别出五十五数，漫标为形洛书者，其三又止于八卦方位而已。是长民不揣其本，其事固非，而泰伯亦元不识此之三，本之则一，而妄析以为三尔。自是已后，愈传愈失，愈失愈凿，至有因「河出图，洛出书」，见于大传，而并致疑大傅非孔子所作者，不知图本非书，书本非图。至其甚者，以五十五数之图乃妄谓之河图，而以图南所传之河图反谓之洛书，颠倒迷缪，靡所底止。殊不明河图八卦明著五十五数，实指以天数五，地数五，而其数自天一地二，以至天五地十，合而五十有五，有体有用，有虚有实，原始要终，而尽发于一图，岂尝别求合于洛书哉？洛书亦岂尝谓五十五数哉？今图南既别无义例辞说，误以图之五十五数别标一图，以为洛书，是其传疑之始也。原其初意，盖由汉儒袭传洪范初一之五行，其二曰火，四曰金，太玄准易实本之，亦以二为火、为南，四为金、为西。今河图乃置二于西南，置四于东南，是火、金改次矣。既不敢遂改河图，乃别以其五十五数析为洛书，而以洪范二火次于南，四金次于西，且以七随二，九随四，而易置其南、西焉。以故长民不识其由，至谓火、金易位也。夫离之数九，居正南为火，兑之数七，居正西为金，乃天地自然参伍以变之数，断断无以易之，岂容以汉儒任意比校洪范火金之二四得而移易之乎？况洪范只有五行之数，今增以七九，又以七随二，九随四，又何所本哉？若校以河图之例，七附二，九附四，是七稽疑当随二五事，「九五福」当随四五纪，则成何义类也？二七、四九，徒论其数，无形象无方位可定，指空移易之则可。离兑之有方所，火金之有体用，岂天地之造化亦遂肯依附人之作为，亦为之变移乎？今图南不谓图书之数较然不可相同，而欲以背理之人为比而同之，截截自分界限，是得指失肩背矣。且河图之出，非徒谓四象八卦之具文也，天地之体用固犹是也。离南象天，离中乃阴，阴所以降。坎北象地，坎中有阳，阳所以升。震阳在初，所以象阳木之东升。兑阴在上，所以象阴金之西降。乾坤所以体天地，阴阳所以用造化，而二卦乃寄于西南西北之维，习于常见，是天地易位矣。不惟是也，筮法又以震、巽为木，乾、兑为金，坤、艮为土，而坎独为水，离独为火，则坎、离得专水火，而乾、坤乃不得专天地，亦犹火金之不可以执方求定也。坤二位于西南，乃地二生火；巽四位于东南，乃地四生金，皆阴也。而兑七位于西，离九位于南，皆阳也。是生数皆阴，必待阳数以成之也。地之生数自西而南，故坤而后巽。成数自南而西，故离而后兑。观于火既炽而灰灭，是火既变而神化。金虽销而质存，是金既化而精犹未变也。此火金之所以互变化者同而不同。故二七四、九之数，自是参伍错综之变，不可以执方究其竟也。今五十五数之图，以一二三四置于四方之内，而以六七八九随置其外者，案其方而数之则可也，不知将何以循序回环以运行之乎？况不知五与十者，特有数寄于四方之位而虚用之也。且五与十虽谓土数，五行家于土必以分王于四方辰戌丑未之位，医家谓土为脾，以五气之运，每运七十二日，总三百六十为期之例，特以土之七十二日四分之，各十八日于四时之附末，谓为脾之主事，医于人至为切已。以土之日四分而试之，以为常验，亦岂常专以土之五总之，而特设五于四方之外，与四方分位而别立之五以为中五哉？况筮法四营而成易，以十有八变而成卦，每变四营，总卦之成凡七十有二营，亦与医说脗合。今图乃分五离立，而特设异五于中位，指以为中，则为此中者，又将孰适于用乎？故余以为图南之别立五十五数标异，谓之「形洛书」者，是其初作已自失之矣。书之九畴，各畴自有成数，如一五行，二五事，犹或得以五行五用之数从而强推引之，至于五皇极，则已不可指实之为何物何事，而甚则九五福而附以六极，则将计九乎？计五福而兼计六极乎？皇极谓大中，而六极者其极又可谓中乎？皇极本非物非事，故可指之为中，今徒实以五点，而五点者乃遂得为中乎？畴自一至九，界界然各存本有之数，不知何自而可以合于五十有五之数，强谓其合者，盖其人之妄也。若其后而至于以书谓图，以图谓书者，又妄人中之妄人也。此余特谓图则有数可通，而书则有畴类可数，而不可布之以为图也。凡余所以专守河图者，非敢自谓亲见羲文所以本之而作易者，而其五且十之数，横斜旁正，相生相成之进退赢缩，一阴一阳之奇耦分合，八体二用之虚实变通，殆有造化神明莫穷之蕴，非人之所能为，而殆乎天地之自然者，宜其为羲文所以作易之本原也。窃尝心潜力索，触类引伸，变而通之，由门入蕴，谓独得一全之体用，僭著其说。然与汉诸儒事事必强推五行以求合于春秋灾异，傅会五十五数以为洛书者，实不敢谓然，不敢同也，世恐未悉。况此河图或谓由易纬乾凿度，谓太一取其数以行九宫，四正四维皆合十五。郑康成又注引其所以行九宫者。至于环中之虚位，本非谓五，而乃谓实为五之中宫，固其纬注俱妄。又不知其为五若十，皆虚用以制其奇耦生成，虽有其数，实无其位也。然其所谓之太一者，与太极则无以异也。苟未识其然，记曰：「夫礼必本于太一，分而为天地，转而为阴阳，变而为四时，列而为鬼神。」其理固与太极无以异也，自可旁通而无间然者，记经之属也，因附诸传后，以征易图通变卷四。",-1)])])}const f=t(r,[["render",o]]);export{_ as __pageData,f as default};
